#include "../../src/scanner.h"
#include "../../src/memory.h"
#include <stdio.h>

/*  Function generated by AI
    AI: ChatGPT
    Prompt: "jak můžu pomocí fprintf vypsat jednotlivé tokeny co dostanu?"
*/
void print_token(token_t token)
{
    fprintf(stdout, "line %u: ", token.line_num);

    switch (token.type) {
        case T_KEY_INT:
            fprintf(stdout, "T_KEY_INT\n");
            break;

        case T_KEY_DOUBLE:
            fprintf(stdout, "T_KEY_DOUBLE\n");
            break;

        case T_KEY_STRING:
            fprintf(stdout, "T_KEY_STRING\n");
            break;

        case T_KEY_DEF:
            fprintf(stdout, "T_KEY_DEF\n");
            break;

        case T_IDENTIFIER:
            fprintf(stdout, "T_IDENTIFIER (%s)\n",
                    token.value.string_value);
            break;

        case T_STRING_LITERAL:
            fprintf(stdout, "T_STRING_LITERAL (\"%s\")\n",
                    token.value.string_value);
            break;

        case T_INT_LITERAL:
            fprintf(stdout, "T_INT_LITERAL (%d)\n",
                    token.value.int_value);
            break;

        case T_DOUBLE_LITERAL:
            fprintf(stdout, "T_DOUBLE_LITERAL (%f)\n",
                    token.value.double_value);
            break;

        case T_PLUS:
            fprintf(stdout, "T_PLUS\n");
            break;

        case T_MINUS:
            fprintf(stdout, "T_MINUS\n");
            break;

        case T_MULT:
            fprintf(stdout, "T_MULT\n");
            break;

        case T_DIV:
            fprintf(stdout, "T_DIV\n");
            break;

        case T_L_ROUND_BRACKET:
            fprintf(stdout, "T_L_ROUND_BRACKET\n");
            break;

        case T_R_ROUND_BRACKET:
            fprintf(stdout, "T_R_ROUND_BRACKET\n");
            break;

        case T_LF:
            fprintf(stdout, "T_LF\n");
            break;

        case T_MORE_INDENT:
            fprintf(stdout, "T_MORE_INDENT\n");
            break;

        case T_LESS_INDENT:
            fprintf(stdout, "T_LESS_INDENT\n");
            break;

        case T_EOF:
            fprintf(stdout, "T_EOF\n");
            break;
        
        case T_AT_MAIN:
            fprintf(stdout, "T_AT_MAIN\n");
            break;
        
        case T_COLON:
            fprintf(stdout, "T_COLON\n");
            break;
        
        case T_KEY_UNIT:
            fprintf(stdout, "T_KEY_UNIT\n");
            break;
        
        case T_ASSIGN:
            fprintf(stdout, "T_ASSIGN\n");
            break;

        case T_KEY_VAL:
            fprintf(stdout, "T_KEY_VAL\n");
            break;
        
        case T_KEY_IMPORT:
            fprintf(stdout, "T_KEY_IMPORT\n");
            break;
        
        case T_DOT:
            fprintf(stdout, "T_DOT\n");
            break;

        case T_KEY_RETURN:
            fprintf(stdout, "T_KEY_RETURN\n");
            break;
        
        case T_UNIT_LITERAL:
            fprintf(stdout, "T_UNIT_LITERAL\n");
            break;

        case T_KEY_VAR:
            fprintf(stdout, "T_KEY_VAR\n");
            break;

        case T_COMMA:
            fprintf(stdout, "T_COMMA\n");
            break;

        default:
            fprintf(stdout, "UNKNOWN TOKEN (%d)\n", token.type);
            break;
    }
}

int main (void) {
    scratch_init();

    token_t output;
    while ((output = get_next_token()).type != T_EOF) {
        print_token(output);
    }
    print_token(output);


    scratch_free();
    return 0;
}